<template><AppLayout><div class="video-task-detail space-y-5"><RouterLink to="/admin/video/tasks" class="video-task-back text-sm text-primary-600">{{ copy.back }}</RouterLink><header class="video-task-header"><h1 class="video-task-title text-2xl font-semibold">{{ copy.title }} #{{ task?.id }}</h1><p class="video-task-description text-sm text-gray-500">{{ copy.description }}</p></header><p v-if="loading" class="video-task-loading text-sm text-gray-500">{{ copy.loading }}</p><p v-else-if="errorMessage" class="video-task-error text-sm text-red-600">{{ errorMessage }}</p><div v-else-if="task" class="video-task-evidence card grid gap-4 p-5 md:grid-cols-2"><div v-for="row in rows" :key="row[0]" class="video-task-field"><div class="video-task-label text-xs text-gray-500">{{ row[0] }}</div><div class="video-task-value mt-1 break-all text-sm">{{ row[1] || '-' }}</div></div><div class="video-task-asset md:col-span-2"><div class="video-task-label text-xs text-gray-500">{{ copy.asset }}</div><a v-if="task.result_url" :href="task.result_url" target="_blank" rel="noreferrer" class="video-task-asset-link break-all text-sm text-primary-600">{{ task.result_url }}</a><span v-else class="video-task-asset-empty">-</span></div></div></div></AppLayout></template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import AppLayout from '@/components/layout/AppLayout.vue'
import { adminAPI } from '@/api/admin'
import type { VideoTaskAdmin } from '@/api/admin/video'
import { extractApiErrorMessage } from '@/utils/apiError'
const route = useRoute(); const task = ref<VideoTaskAdmin>(); const loading = ref(true); const errorMessage = ref('')
const copy = { back: '\u8fd4\u56de\u4efb\u52a1\u8bc1\u636e', title: '\u89c6\u9891\u4efb\u52a1', description: '\u53ea\u5c55\u793a\u771f\u5b9e\u5b57\u6bb5\uff1b\u5931\u8d25\u8c03\u7528\u4e0d\u4f1a\u964d\u7ea7\u4e3a\u6a21\u62df\u6210\u529f\u3002', loading: '\u6b63\u5728\u52a0\u8f7d\u4efb\u52a1\u8bc1\u636e\u2026', asset: '\u7ed3\u679c\u8d44\u4ea7\u5730\u5740' }
const rows = computed(() => task.value ? [['\u4efb\u52a1\u72b6\u6001', task.value.status], ['\u4e0a\u6e38\u4efb\u52a1 ID', task.value.upstream_task_id], ['\u771f\u5b9e\u8c03\u7528\u6b21\u6570', String(task.value.real_dispatch_count)], ['\u7ed3\u7b97\u8d39\u7528', `${task.value.cost_amount} ${task.value.currency || 'USD'}`], ['\u4e0a\u6e38\u5b9e\u9645\u8d39\u7528 (USD)', String(task.value.provider_actual_cost_usd)], ['\u8c03\u5ea6\u72b6\u6001', task.value.dispatch_state], ['\u4e0a\u6e38\u9519\u8bef\u7801', task.value.provider_error_code], ['\u5931\u8d25\u539f\u56e0', task.value.error_message || task.value.provider_error_message], ['\u5c3e\u5e27\u5730\u5740', task.value.last_frame_url], ['\u6a21\u578b', task.value.model], ['\u521b\u5efa\u4eba', String(task.value.created_by)]] : [])
onMounted(async () => { try { task.value = await adminAPI.video.getTask(Number(route.params.id)) } catch (error) { errorMessage.value = extractApiErrorMessage(error, '\u52a0\u8f7d\u4efb\u52a1\u8bc1\u636e\u5931\u8d25') } finally { loading.value = false } })
</script>
